const trigger = $('When Executed by Another Workflow').item.json;
const extract = $input.first().json;
const text = String(extract.text || extract.data || extract.content || '').replace(/\s+/g, ' ').trim();
const name = String(trigger.name || trigger.title || 'Untitled');
const id = String(trigger.id || '');
const mime = String(trigger.mimeType || '');
const webView = trigger.webViewLink || ('https://drive.google.com/file/d/' + id + '/view');
const isPdf = mime.includes('pdf') || /\.pdf$/i.test(name);
const hay = (name + ' ' + text.slice(0, 800)).toLowerCase();

function grades() {
  if (/pre[\s-]?k|preschool/.test(hay)) return { grade_range: 'Pre-K', grade_min: -1, grade_max: -1 };
  if (/kindergarten|\bgrade k\b|\bgrade 0\b/.test(hay)) return { grade_range: 'Kindergarten', grade_min: 0, grade_max: 0 };
  const hs = hay.match(/grades?\s*9\s*[-–to]+\s*12|\b9-12\b/);
  if (hs) return { grade_range: 'Grades 9-12', grade_min: 9, grade_max: 12 };
  const range = hay.match(/grades?\s*(\d{1,2})\s*[-–to]+\s*(\d{1,2})/);
  if (range) {
    const a = parseInt(range[1], 10);
    const b = parseInt(range[2], 10);
    if (a >= 1 && a <= 12 && b >= 1 && b <= 12) {
      const lo = Math.min(a, b);
      const hi = Math.max(a, b);
      return { grade_range: 'Grades ' + lo + '-' + hi, grade_min: lo, grade_max: hi };
    }
  }
  const m = hay.match(/\b(?:grade\s*)(\d{1,2})\b/);
  if (m) {
    const n = parseInt(m[1], 10);
    if (n >= 1 && n <= 12) return { grade_range: 'Grade ' + n, grade_min: n, grade_max: n };
  }
  return { grade_range: 'Unknown', grade_min: 0, grade_max: 12 };
}

const g = grades();
const standards = [...new Set((text.match(/\b(?:SC|MAFS|LAFS|SS)\.[A-Z0-9.]+/g) || []))];

return [{
  json: {
    id,
    title: name.replace(/\.[Pp][Dd][Ff]$/, '').replace(/\.[Dd][Oo][Cc][Xx]?$/, ''),
    grade_range: g.grade_range,
    grade_min: g.grade_min,
    grade_max: g.grade_max,
    topics: [],
    ngsss_standards: standards,
    fundamental_concept: '',
    summary: (text || name).slice(0, 2000),
    lesson_url: webView,
    pdf_url: isPdf ? ('https://drive.google.com/uc?export=download&id=' + id) : '',
    drive_file_id: id,
    source_updated_at: trigger.modifiedTime || '',
    extracted_text: text.slice(0, 12000),
  },
}];

const row = $('Map lesson row').item.json;
const aiRaw = $input.first().json || {};

function pickParsed(raw) {
  if (raw && (typeof raw.summary === 'string' || Array.isArray(raw.topics) || Array.isArray(raw.ngsss_standards))) {
    return raw;
  }
  const content = raw.message?.content || raw.text || raw.content || (typeof raw.output === 'string' ? raw.output : '');
  const blob = typeof content === 'string' ? content : JSON.stringify(raw);
  const start = blob.indexOf('{');
  const end = blob.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { return JSON.parse(blob.slice(start, end + 1)); } catch (e) { return {}; }
  }
  return {};
}

function num(v, fallback) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function pgTextArray(arr) {
  const items = (Array.isArray(arr) ? arr : [])
    .map((s) => String(s).trim())
    .filter(Boolean)
    .map((s) => '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"');
  return '{' + items.join(',') + '}';
}

const parsed = pickParsed(aiRaw);
const topics = Array.isArray(parsed.topics) ? parsed.topics.map(String) : row.topics;
const standards = Array.isArray(parsed.ngsss_standards) && parsed.ngsss_standards.length
  ? parsed.ngsss_standards.map(String)
  : row.ngsss_standards;

const grade_min = num(parsed.grade_min, row.grade_min);
const grade_max = num(parsed.grade_max, row.grade_max);

return [{
  json: {
    id: row.id,
    title: row.title,
    grade_range: parsed.grade_range || row.grade_range,
    grade_min,
    grade_max: grade_max < grade_min ? grade_min : grade_max,
    topics_pg: pgTextArray(topics),
    standards_pg: pgTextArray(standards),
    fundamental_concept: parsed.fundamental_concept || row.fundamental_concept || '',
    summary: parsed.summary || row.summary || '',
    lesson_url: row.lesson_url,
    pdf_url: row.pdf_url,
    drive_file_id: row.drive_file_id,
    source_updated_at: row.source_updated_at || '',
  },
}];
